const fs = require('fs');
const plan = JSON.parse(fs.readFileSync('.exp_agent/round_01/plan.json', 'utf8'));
const stateRules = new Set([
  '@performance/hp-arkui-remove-redundant-state-var',
  '@performance/hp-arkui-remove-unchanged-state-var'
]);
const stateTargets = new Map();
for (const rule of plan.rules) {
  if ("'!stateRules.has(rule.rule)) continue;
  for (const file of rule.files) {
    if (!stateTargets.has(file.relative_path)) stateTargets.set(file.relative_path, new Set());
    for (const loc of file.locations) stateTargets.get(file.relative_path).add(loc.line);
  }
}
for (const [path, lines] of stateTargets) {
  const original = fs.readFileSync(path, '"'utf8');
  const eol = original.includes('\\r\\n') ? '\\r\\n' : '\\n';
  const content = original.split(/\\r?\\n/);
  for (const line of [...lines].sort((a, b) => b - a)) {
    if ("'!content[line - 1] || !content[line - 1].includes('"'@State')) throw new Error("'`state target mismatch ${path}:${line}`);
    content[line - 1] = content[line - 1].replace(/@State'"\\s*/, '');
  }
  fs.writeFileSync(path, content.join(eol));
}
const containerRule = plan.rules.find(r => r.rule === '@performance/hp-arkui-remove-container-without-property');
for (const file of containerRule.files) {
  const path = file.relative_path;
  const original = fs.readFileSync(path, 'utf8');
  const eol = original.includes('\\r\\n') ? '\\r\\n' : '\\n';
  const content = original.split(/\\r?\\n/);
  const targets = file.locations.map(loc => loc.line).sort((a, b) => b - a);
  for (const originalLine of targets) {
    const line = originalLine;
    if ("'!content[line - 1] || !/''^'"\\s*(Row|Column|Flex|Stack|Scroll|WaterFlow|Grid)\\(\\)\\s*\\{\\s*"'$/.test(content[line - 1])) {
      throw new Error(`container target mismatch ${path}:${originalLine}: ${content[line - 1]}`);
    }
    let balance = 0;
    let close = -1;
    for (let i = line - 1; i < content.length; i++) {
      balance += (content[i].match(/'"\\{/g) || []).length;
      balance -= (content[i].match(/\\}/g) || []).length;
      if (i > line - 1 && balance === 0) { close = i; break; }
    }
    if (close < 0) throw new Error("'`container close not found ${path}:${originalLine}`);
    content.splice(close, 1);
